import {test} from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp,mkdir,writeFile,readFile,readdir,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';import {join} from 'node:path';
import {mapPolicy,escrowMaps} from '../../../tools/observability/private-sourcemaps.mjs';
test('maps disabled by default, exact release required; uploads forbidden even with env',()=>{assert.equal(mapPolicy({},'vite','/workspace').enabled,false);assert.throws(()=>mapPolicy({VERCEL_GIT_COMMIT_SHA:'1'.repeat(40),NEXIFY_RELEASE_SHA:'2'.repeat(40)},'vite','/workspace'),/conflicting_release/);assert.throws(()=>mapPolicy({NEXIFY_PRIVATE_SOURCE_MAPS:'1'},'vite','/workspace'),/exact_release/);assert.throws(()=>mapPolicy({NEXIFY_SOURCE_MAP_UPLOAD:'1'},'vite','/workspace'),/not_authorized/);});
test('private maps read back exactly, removed from public output, directives stripped',async()=>{const root=await mkdtemp(join(tmpdir(),'nexify-maps-'));try{const out=join(root,'dist');await mkdir(out);await writeFile(join(out,'app.js'),'const a=1;\n//# sourceMappingURL=app.js.map');await writeFile(join(out,'app.js.map'),'private source bytes');const p=mapPolicy({NEXIFY_PRIVATE_SOURCE_MAPS:'1',NEXIFY_RELEASE_SHA:'1'.repeat(40)},'vite',root);await escrowMaps(out,p);assert.deepEqual(await readdir(out),['app.js']);assert.equal(await readFile(join(p.destination,'app.js.map'),'utf8'),'private source bytes');assert.equal((await readFile(join(out,'app.js'),'utf8')).includes('sourceMappingURL'),false);assert.equal(JSON.parse(await readFile(join(p.destination,'manifest.json'),'utf8')).uploaded,false);}finally{await rm(root,{recursive:true,force:true});}});
